def detect_action_loop(trajectory):
    actions = [t['action'] for t in trajectory]
    if len(actions) < 6:
        return False, 0
    for plen in [1, 2, 3]:
        for i in range(len(actions) - plen * 3 + 1):
            pattern = actions[i:i+plen]
            repeats = 1
            j = i + plen
            while j + plen <= len(actions) and actions[j:j+plen] == pattern:
                repeats += 1
                j += plen
            if repeats >= 4:
                return True, repeats
    return False, 0

def detect_exploration_wandering(trajectory):
    actions = [t['action'] for t in trajectory]
    go_actions = [a for a in actions if a.startswith('go to')]
    if len(go_actions) >= 15:
        visited = set()
        revisits = 0
        for a in go_actions:
            if a in visited:
                revisits += 1
            visited.add(a)
        if revisits >= 5:
            return True
    return False

def detect_object_not_found(trajectory):
    actions = [t['action'] for t in trajectory]
    go_count = sum(1 for a in actions if a.startswith('go to'))
    take_count = sum(1 for a in actions if a.startswith('take') or a.startswith('pick'))
    return go_count >= 10 and take_count == 0

def detect_missing_subgoal(task_type, trajectory):
    actions = [t['action'].lower() for t in trajectory]
    if 'clean' in task_type:
        has_clean = any('clean' in a or 'sinkbasin' in a for a in actions)
        has_put = any('put' in a for a in actions)
        if has_put and not has_clean:
            return True
    elif 'heat' in task_type:
        has_heat = any('heat' in a or 'microwave' in a for a in actions)
        has_put = any('put' in a for a in actions)
        if has_put and not has_heat:
            return True
    elif 'cool' in task_type:
        has_cool = any('cool' in a or 'fridge' in a for a in actions)
        has_put = any('put' in a for a in actions)
        if has_put and not has_cool:
            return True
    return False

def classify_failure(task_type, trajectory, steps):
    if not trajectory:
        return 'no_trajectory'
    is_loop, repeats = detect_action_loop(trajectory)
    if is_loop and repeats >= 4:
        return 'loop_repetition'
    if detect_missing_subgoal(task_type, trajectory):
        return 'missing_subgoal'
    if detect_object_not_found(trajectory):
        return 'object_not_found'
    if detect_exploration_wandering(trajectory):
        return 'exploration_wandering'
    if steps >= 48:
        return 'max_steps_exhaustion'
    return 'other'

